"use client";
import { Suspense, useEffect, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { api } from "@/lib/api";
import { useAuth } from "../_providers/AuthProvider";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select } from "@/components/ui/select";

function decodeRole(token) {
  try {
    const payload = JSON.parse(atob(token.split(".")[1]));
    return payload.role;
  } catch {
    return null;
  }
}

function AuthPageInner() {
  const params = useSearchParams();
  const router = useRouter();
  const { login, isAuthenticated, role: userRole, ready } = useAuth();

  const [mode, setMode] = useState(params.get("mode") === "register" ? "register" : "login");
  const [form, setForm] = useState({
    email: "",
    password: "",
    role: params.get("role") || "student",
    company_name: "",
  });
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (ready && isAuthenticated && userRole) {
      router.replace(`/${userRole}`);
    }
  }, [ready, isAuthenticated, userRole, router]);

  const update = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const submit = async (e) => {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const path = mode === "register" ? "/auth/register" : "/auth/login";
      const payload =
        mode === "register"
          ? {
              email: form.email,
              password: form.password,
              role: form.role,
              company_name: form.role === "company" ? form.company_name || "Pending Company" : undefined,
            }
          : { email: form.email, password: form.password };

      const data = await api(path, { method: "POST", body: JSON.stringify(payload) });
      login(data.access_token, data.refresh_token);
      const role = decodeRole(data.access_token) || "student";
      router.replace(`/${role}`);
    } catch (err) {
      setError(err.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center px-4 py-12">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle>
            {mode === "register" ? "Create your CareerBridge account" : "Welcome back"}
          </CardTitle>
          <CardDescription>
            {mode === "register"
              ? "Sign up as a student, company, or administrator."
              : "Log in to access your dashboard."}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={submit} className="space-y-3">
            <div>
              <Label htmlFor="email">Email</Label>
              <Input id="email" type="email" required value={form.email} onChange={update("email")} placeholder="you@example.com" />
            </div>
            <div>
              <Label htmlFor="password">Password</Label>
              <Input id="password" type="password" required minLength={8} value={form.password} onChange={update("password")} placeholder="At least 8 characters" />
            </div>
            {mode === "register" && (
              <>
                <div>
                  <Label htmlFor="role">Role</Label>
                  <Select id="role" value={form.role} onChange={update("role")}>
                    <option value="student">Student</option>
                    <option value="company">Company (requires admin approval)</option>
                    <option value="admin">Administrator</option>
                  </Select>
                </div>
                {form.role === "company" && (
                  <div>
                    <Label htmlFor="company_name">Company name</Label>
                    <Input id="company_name" required value={form.company_name} onChange={update("company_name")} placeholder="e.g. Acme Software" />
                  </div>
                )}
              </>
            )}
            {error && (
              <p className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">
                {error}
              </p>
            )}
            <Button type="submit" disabled={busy} className="w-full">
              {busy ? "Please wait..." : mode === "register" ? "Create account" : "Log in"}
            </Button>
          </form>
          <div className="mt-4 text-center text-sm text-muted-foreground">
            {mode === "register" ? (
              <>
                Already have an account?{" "}
                <button className="text-accent underline" onClick={() => setMode("login")}>
                  Log in
                </button>
              </>
            ) : (
              <>
                New here?{" "}
                <button className="text-accent underline" onClick={() => setMode("register")}>
                  Create an account
                </button>
              </>
            )}
          </div>
          <div className="mt-4 text-center text-xs text-muted-foreground">
            <Link href="/" className="hover:underline">
              ← Back home
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default function AuthPage() {
  return (
    <Suspense fallback={<div className="flex min-h-screen items-center justify-center text-muted-foreground">Loading...</div>}>
      <AuthPageInner />
    </Suspense>
  );
}
